async function heroUpgrade(env,a,heroId){const s=await stateOf(env,a.id),h=s.owned?.[heroId];if(!h)return J({error:"HERO_NOT_OWNED"},404);const old=h.level||1,cost=150*old;if(s.gold<cost)return J({error:"GOLD_NOT_ENOUGH",message:"GOLD_NOT_ENOUGH"},409);s.gold-=cost;h.level=old+1;h.rank=h.rank||1;await save(env,a.id,s);await env.DB.prepare("INSERT INTO hero_growth_records(player_id,hero_id,action,old_value,new_value,cost_json)VALUES(?,?,?,?,?,?)").bind(a.id,heroId,"LEVEL_UP",old,h.level,JSON.stringify({gold:cost})).run();return J({state:s,level:h.level,cost:{gold:cost}})}
async function heroRankUp(env,a,heroId){const s=await stateOf(env,a.id),h=s.owned?.[heroId];if(!h)return J({error:"HERO_NOT_OWNED"},404);const old=h.rank||1;if(old>=5)return J({error:"MAX_RANK",message:"MAX_RANK"},409);const cost={gold:old*1200,core:old};if(s.gold<cost.gold||(s.inventory.core||0)<cost.core)return J({error:"MATERIAL_NOT_ENOUGH",message:"MATERIAL_NOT_ENOUGH"},409);s.gold-=cost.gold;s.inventory.core-=cost.core;h.rank=old+1;await save(env,a.id,s);await env.DB.prepare("INSERT INTO hero_growth_records(player_id,hero_id,action,old_value,new_value,cost_json)VALUES(?,?,?,?,?,?)").bind(a.id,heroId,"RANK_UP",old,h.rank,JSON.stringify(cost)).run();return J({state:s,rank:h.rank,cost})}
async function shopBuy(req,env,a){const b=await req.json(),item=SHOP[b.itemId],qty=limit(b.quantity,1,20);if(!item)return J({error:"ITEM_NOT_FOUND"},404);const date=taipeiDate(),limitPerDay=item.kind==="equipment"?1:5;const used=(await env.DB.prepare("SELECT quantity FROM shop_daily_purchases WHERE player_id=? AND purchase_date=? AND item_id=?").bind(a.id,date,b.itemId).first())?.quantity||0;if(used+qty>limitPerDay)return J({error:"DAILY_LIMIT",message:"DAILY_LIMIT"},409);const total=item.price*qty,s=await stateOf(env,a.id);if(s.gold<total)return J({error:"GOLD_NOT_ENOUGH",message:"GOLD_NOT_ENOUGH"},409);s.gold-=total;if(item.kind==="equipment")s.inventory.equipment[b.itemId]=(s.inventory.equipment[b.itemId]||0)+qty;else s.inventory[b.itemId]=(s.inventory[b.itemId]||0)+qty;await save(env,a.id,s);await env.DB.batch([env.DB.prepare("INSERT INTO shop_transactions(player_id,item_id,quantity,gold_cost)VALUES(?,?,?,?)").bind(a.id,b.itemId,qty,total),env.DB.prepare(`INSERT INTO shop_daily_purchases(player_id,purchase_date,item_id,quantity)VALUES(?,?,?,?) ON CONFLICT(player_id,purchase_date,item_id) DO UPDATE SET quantity=quantity+excluded.quantity`).bind(a.id,date,b.itemId,qty)]);return J({state:s,itemId:b.itemId,quantity:qty,goldCost:total})}
async function useItem(req,env,a){const {itemId}=await req.json(),s=await stateOf(env,a.id);if(itemId!=="energyPotion")return J({error:"ITEM_NOT_USABLE"},409);if((s.inventory.energyPotion||0)<1)return J({error:"ITEM_NOT_ENOUGH",message:"ITEM_NOT_ENOUGH"},409);if(s.energy>=s.maxEnergy)return J({error:"ENERGY_FULL",message:"ENERGY_FULL"},409);const before=s.energy;s.inventory.energyPotion--;s.energy=Math.min(s.maxEnergy,s.energy+10);await save(env,a.id,s);await env.DB.prepare("INSERT INTO item_use_records(player_id,item_id,quantity,effect_json)VALUES(?,?,1,?)").bind(a.id,itemId,JSON.stringify({energyBefore:before,energyAfter:s.energy})).run();return J({state:s,effect:{energy:s.energy-before}})}
