async function equipmentEnhance(req,env,a){const {equipmentId}=await req.json(),s=await stateOf(env,a.id);if((s.inventory.equipment[equipmentId]||0)<1)return J({error:"ITEM_NOT_ENOUGH"},409);const m=s.equipmentMeta[equipmentId]||{level:0,refine:0},cost={gold:(m.level+1)*500,ore:m.level+1};if(s.gold<cost.gold||(s.inventory.ore||0)<cost.ore)return J({error:"MATERIAL_NOT_ENOUGH",message:"MATERIAL_NOT_ENOUGH"},409);s.gold-=cost.gold;s.inventory.ore-=cost.ore;m.level++;s.equipmentMeta[equipmentId]=m;await save(env,a.id,s);await env.DB.prepare(`INSERT INTO equipment_progress(player_id,equipment_id,enhance_level,refine_level)VALUES(?,?,?,?) ON CONFLICT(player_id,equipment_id) DO UPDATE SET enhance_level=excluded.enhance_level,refine_level=excluded.refine_level,updated_at=CURRENT_TIMESTAMP`).bind(a.id,equipmentId,m.level,m.refine).run();return J({state:s,level:m.level})}
async function equipmentRefine(req,env,a){const {equipmentId}=await req.json(),s=await stateOf(env,a.id);if((s.inventory.equipment[equipmentId]||0)<1)return J({error:"ITEM_NOT_ENOUGH"},409);const m=s.equipmentMeta[equipmentId]||{level:0,refine:0},cost={gold:(m.refine+1)*1200,core:m.refine+1};if(s.gold<cost.gold||(s.inventory.core||0)<cost.core)return J({error:"MATERIAL_NOT_ENOUGH",message:"MATERIAL_NOT_ENOUGH"},409);s.gold-=cost.gold;s.inventory.core-=cost.core;m.refine++;s.equipmentMeta[equipmentId]=m;await save(env,a.id,s);await env.DB.prepare(`INSERT INTO equipment_progress(player_id,equipment_id,enhance_level,refine_level)VALUES(?,?,?,?) ON CONFLICT(player_id,equipment_id) DO UPDATE SET enhance_level=excluded.enhance_level,refine_level=excluded.refine_level,updated_at=CURRENT_TIMESTAMP`).bind(a.id,equipmentId,m.level,m.refine).run();return J({state:s,refine:m.refine})}
async function equipmentDismantle(req,env,a){const {equipmentId}=await req.json(),s=await stateOf(env,a.id);if((s.inventory.equipment[equipmentId]||0)<1)return J({error:"ITEM_NOT_ENOUGH"},409);s.inventory.equipment[equipmentId]--;s.inventory.ore=(s.inventory.ore||0)+2;s.inventory.wood=(s.inventory.wood||0)+2;await save(env,a.id,s);await env.DB.prepare("INSERT INTO equipment_dismantles(player_id,equipment_id,reward_json)VALUES(?,?,?)").bind(a.id,equipmentId,JSON.stringify({ore:2,wood:2})).run();return J({state:s,reward:{ore:2,wood:2}})}
async function battleItem(req,env,a){const {itemId}=await req.json(),s=await stateOf(env,a.id);if(itemId!=="potion"||(s.inventory.potion||0)<1)return J({error:"ITEM_NOT_ENOUGH"},409);s.inventory.potion--;await save(env,a.id,s);return J({state:s})}
async function dungeonClear(req,env,a){const {dungeonId}=await req.json(),s=await stateOf(env,a.id),date=taipeiDate(),cfg=dungeonId==="gold"?{energy:6,reward:{gold:1800}}:dungeonId==="material"?{energy:6,reward:{wood:3,ore:3,herb:3}}:null;if(!cfg)return J({error:"NOT_FOUND"},404);const used=Number((await env.DB.prepare("SELECT used_count FROM dungeon_daily_attempts WHERE player_id=? AND dungeon_id=? AND attempt_date=?").bind(a.id,dungeonId,date).first())?.used_count||0);if(used>=3)return J({error:"DAILY_LIMIT"},409);if(s.energy<cfg.energy)return J({error:"ENERGY_NOT_ENOUGH"},409);s.energy-=cfg.energy;applyReward(s,cfg.reward);await save(env,a.id,s);await env.DB.prepare(`INSERT INTO dungeon_daily_attempts(player_id,dungeon_id,attempt_date,used_count)VALUES(?,?,?,1) ON CONFLICT(player_id,dungeon_id,attempt_date) DO UPDATE SET used_count=used_count+1`).bind(a.id,dungeonId,date).run();return J({state:s,reward:cfg.reward})}
async function eventStatus(env,a){const date=taipeiDate(),rows=(await env.DB.prepare("SELECT day_index FROM event_checkins WHERE player_id=? AND campaign_key=? ORDER BY day_index").bind(a.id,date.slice(0,7)).all()).results,claimedDays=rows.map(x=>Number(x.day_index)),todayDay=Math.min(7,claimedDays.length+1);return J({claimedDays,todayDay,claimedToday:claimedDays.includes(todayDay)})}
async function eventCheckin(env,a){const campaign=taipeiDate().slice(0,7),status=await eventStatus(env,a).then(r=>r.json()),day=status.todayDay;if(status.claimedToday)return J({error:"ALREADY_CLAIMED"},409);const reward=day===7?{gems:300,core:3}:{gold:300+day*100,gems:30};const s=await stateOf(env,a.id);applyReward(s,reward);await save(env,a.id,s);await env.DB.prepare("INSERT INTO event_checkins(player_id,campaign_key,day_index)VALUES(?,?,?)").bind(a.id,campaign,day).run();return J({state:s,reward,status:{claimedDays:[...status.claimedDays,day],todayDay:Math.min(7,day+1),claimedToday:true}})}
async function eventStage(req,env,a){const {eventStageId}=await req.json(),s=await stateOf(env,a.id);if(eventStageId!=="starlight")return J({error:"NOT_FOUND"},404);if(s.energy<8)return J({error:"ENERGY_NOT_ENOUGH"},409);s.energy-=8;const reward={gems:80,core:1};applyReward(s,reward);await save(env,a.id,s);return J({state:s,reward})}
async function guildAssists(env,a){const claimedToday=!!(await env.DB.prepare("SELECT 1 FROM guild_assists WHERE player_id=? AND assist_date=?").bind(a.id,taipeiDate()).first()),rows=(await env.DB.prepare("SELECT id,display_name,stage_unlocked FROM players WHERE id<>? ORDER BY stage_unlocked DESC LIMIT 20").bind(a.id).all()).results;return J({claimedToday,players:rows.map(x=>({id:x.id,displayName:x.display_name,stageUnlocked:x.stage_unlocked,power:x.stage_unlocked*1000}))})}
async function guildAssist(req,env,a){const {helperPlayerId}=await req.json(),date=taipeiDate();if(await env.DB.prepare("SELECT 1 FROM guild_assists WHERE player_id=? AND assist_date=?").bind(a.id,date).first())return J({error:"ALREADY_CLAIMED"},409);if(!await env.DB.prepare("SELECT 1 FROM players WHERE id=?").bind(helperPlayerId).first())return J({error:"PLAYER_NOT_FOUND"},404);const s=await stateOf(env,a.id),reward={gold:500,energy:5};applyReward(s,reward);await save(env,a.id,s);await env.DB.prepare("INSERT INTO guild_assists(player_id,helper_player_id,assist_date)VALUES(?,?,?)").bind(a.id,helperPlayerId,date).run();return J({state:s,reward})}
async function summon(req,env,a){const {count}=await req.json(),n=count===10?10:1,cost=n===10?900:100,s=await stateOf(env,a.id);if(s.gems<cost)return J({error:"GEMS_NOT_ENOUGH"},409);s.gems-=cost;const out=[];for(let i=0;i<n;i++){const r=Math.random(),rarity=r<.05?"傳說":r<.28?"史詩":"稀有",pool=HEROES.filter(h=>h.rarity===rarity),h=pool[Math.floor(Math.random()*pool.length)];out.push(h);if(s.owned[h.id])s.owned[h.id].copies=(s.owned[h.id].copies||1)+1;else s.owned[h.id]={level:1,rank:1,xp:0,copies:1,equipment:{}}}await save(env,a.id,s);return J({state:s,heroes:out})}
async function daily(env,a){const s=await stateOf(env,a.id),date=taipeiDate();if(s.dailyClaimed===date)return J({error:"ALREADY_CLAIMED"},409);const reward={gold:500,gems:80,energy:10};s.dailyClaimed=date;s.gold+=500;s.gems+=80;s.energy=Math.min(s.maxEnergy,s.energy+10);await save(env,a.id,s);return J({state:s,reward})}
async function battleStart(req,env,a){const {stageId}=await req.json(),cfg=STAGES[stageId],s=await stateOf(env,a.id);if(!cfg)return J({error:"NOT_FOUND"},404);if(s.energy<cfg.energy)return J({error:"ENERGY_NOT_ENOUGH"},409);const pending=await env.DB.prepare("SELECT id FROM pending_battles WHERE player_id=? AND settled_at IS NULL").bind(a.id).first();if(pending)return J({error:"BATTLE_PENDING"},409);s.energy-=cfg.energy;await save(env,a.id,s);const id=crypto.randomUUID();await env.DB.prepare("INSERT INTO pending_battles(id,player_id,stage_id)VALUES(?,?,?)").bind(id,a.id,stageId).run();return J({battleId:id})}
async function battleSettle(req,env,a){const {battleId,result}=await req.json(),b=await env.DB.prepare("SELECT * FROM pending_battles WHERE id=? AND player_id=? AND settled_at IS NULL").bind(battleId,a.id).first();if(!b)return J({error:"NOT_FOUND"},404);const s=await stateOf(env,a.id),reward=result==="WIN"?STAGES[b.stage_id]:{};if(result==="WIN"){applyReward(s,reward);for(const id of s.team||[]){const h=s.owned?.[id];if(h)h.xp=(h.xp||0)+(reward.xp||0)}if(b.stage_id===s.stageUnlocked&&s.stageUnlocked<10)s.stageUnlocked++}await save(env,a.id,s);await env.DB.batch([env.DB.prepare("UPDATE pending_battles SET settled_at=CURRENT_TIMESTAMP,result=? WHERE id=?").bind(result,battleId),env.DB.prepare("INSERT INTO battle_records(player_id,stage_id,result)VALUES(?,?,?)").bind(a.id,b.stage_id,result)]);return J({state:s,reward})}
async function missions(env,a){const date=taipeiDate(),s=await stateOf(env,a.id),claims=(await env.DB.prepare("SELECT mission_id FROM mission_claims WHERE player_id=? AND claim_date=?").bind(a.id,date).all()).results.map(x=>x.mission_id),wins=Number((await env.DB.prepare("SELECT COUNT(*) c FROM battle_records WHERE player_id=? AND result='WIN' AND date(created_at)=?").bind(a.id,date).first())?.c||0),defs=[{id:"battle1",icon:"⚔️",title:"完成 1 場戰鬥",description:"任意主線戰鬥勝利",progress:wins,target:1,reward:{gold:300}},{id:"energy",icon:"⚡",title:"消耗體力",description:"今日登入即可領取測試獎勵",progress:s.energy<30?1:0,target:1,reward:{gems:30}}];return J({missions:defs.map(m=>({...m,complete:m.progress>=m.target,claimed:claims.includes(m.id),rewardLabel:rewardLabel(m.reward)}))})}
async function claimMission(env,a,id){const r=await missions(env,a).then(x=>x.json()),m=r.missions.find(x=>x.id===id);if(!m||!m.complete)return J({error:"NOT_COMPLETE"},409);if(m.claimed)return J({error:"ALREADY_CLAIMED"},409);const s=await stateOf(env,a.id);applyReward(s,m.reward);await save(env,a.id,s);await env.DB.prepare("INSERT INTO mission_claims(player_id,mission_id,claim_date)VALUES(?,?,?)").bind(a.id,id,taipeiDate()).run();return J({state:s,reward:m.reward})}
async function mailList(env,a){const rows=(await env.DB.prepare("SELECT * FROM player_mail WHERE player_id=? ORDER BY created_at DESC LIMIT 100").bind(a.id).all()).results;return J({mail:rows.map(x=>({...x,rewardLabel:rewardLabel(parse(x.reward_json,{}))}))})}
