const ARENA_HERO_BASE={aria:{hp:620,atk:105,def:65,spd:90,crit:.14,role:"DPS"},mira:{hp:480,atk:135,def:48,spd:88,crit:.12,role:"DPS"},gorn:{hp:920,atk:76,def:105,spd:60,crit:.08,role:"TANK"},luna:{hp:580,atk:105,def:62,spd:84,crit:.1,role:"HEAL"},kael:{hp:500,atk:168,def:45,spd:118,crit:.24,role:"DPS"},elwyn:{hp:520,atk:126,def:52,spd:104,crit:.18,role:"DPS"},sol:{hp:780,atk:142,def:92,spd:78,crit:.13,role:"DPS"},nyx:{hp:510,atk:154,def:50,spd:96,crit:.16,role:"DPS"}};
function arenaUnitStats(s,id){const h=s.owned?.[id]||{level:1,rank:1,skillLevel:1,equipment:{}},b=ARENA_HERO_BASE[id]||ARENA_HERO_BASE.aria;const lv=Math.max(1,Number(h.level||1)),rank=Math.max(1,Number(h.rank||1)),skill=Math.max(1,Number(h.skillLevel||1));let equipLv=0,refine=0;for(const eq of Object.values(h.equipment||{})){if(!eq)continue;const m=s.equipmentMeta?.[eq]||{};equipLv+=Number(m.level||0);refine+=Number(m.refine||0)}const mult=1+(lv-1)*.075+(rank-1)*.16+equipLv*.025+refine*.06;return{id,name:id,maxHp:Math.round(b.hp*mult),hp:Math.round(b.hp*mult),atk:Math.round(b.atk*mult*(1+(skill-1)*.025)),def:Math.round(b.def*mult),spd:Math.round(b.spd+(lv-1)*.25+rank*2),crit:Math.min(.65,b.crit+(skill-1)*.01+refine*.015),role:b.role,level:lv,rank,skill}}
function arenaPower(s,team){return (team||[]).reduce((t,id)=>{const u=arenaUnitStats(s,id);return t+Math.round(u.maxHp*.34+u.atk*4.1+u.def*3.2+u.spd*2)},0)}
function seededRandom(seed){let h=2166136261;for(const c of seed)h=Math.imul(h^c.charCodeAt(0),16777619);return()=>{h+=0x6D2B79F5;let t=h;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296}}
function aliveUnits(team){return team.filter(x=>x.hp>0)}
function chooseTarget(units,strategy,rng){const alive=aliveUnits(units);if(!alive.length)return null;if(strategy==="FOCUS")return [...alive].sort((a,b)=>a.hp-b.hp)[0];if(strategy==="HEAL")return [...alive].sort((a,b)=>b.atk-a.atk)[0];return alive[Math.floor(rng()*alive.length)]}
function simulateArenaBattle(myState,myTeamIds,enemyState,enemyTeamIds,myStrategy,enemyStrategy,seed){const rng=seededRandom(seed),A=myTeamIds.map(id=>arenaUnitStats(myState,id)),D=enemyTeamIds.map(id=>arenaUnitStats(enemyState,id));const turns=[];let round=0;while(aliveUnits(A).length&&aliveUnits(D).length&&round<60){round++;const order=[...aliveUnits(A).map(u=>({u,side:"ATTACKER"})),...aliveUnits(D).map(u=>({u,side:"DEFENDER"}))].sort((x,y)=>y.u.spd-x.u.spd+(rng()-.5)*8);for(const entry of order){const actor=entry.u;if(actor.hp<=0)continue;const allies=entry.side==="ATTACKER"?A:D,enemies=entry.side==="ATTACKER"?D:A,strategy=entry.side==="ATTACKER"?myStrategy:enemyStrategy;if(!aliveUnits(enemies).length)break;const low=[...aliveUnits(allies)].sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp)[0];const canHeal=(actor.role==="HEAL"||strategy==="HEAL")&&low&&low.hp/low.maxHp<.62&&rng()<.58;if(canHeal){const before=low.hp,amount=Math.round(actor.atk*(1.1+actor.skill*.04));low.hp=Math.min(low.maxHp,low.hp+amount);turns.push({round,side:entry.side,actor:actor.id,target:low.id,action:"HEAL",value:low.hp-before,targetHp:low.hp,targetMaxHp:low.maxHp,critical:false});continue}const target=chooseTarget(enemies,strategy,rng);if(!target)break;const crit=rng()<actor.crit,variance=.92+rng()*.16,raw=actor.atk*(crit?1.75:1)*variance,dmg=Math.max(1,Math.round(raw*100/(100+target.def)));target.hp=Math.max(0,target.hp-dmg);turns.push({round,side:entry.side,actor:actor.id,target:target.id,action:strategy==="FOCUS"?"FOCUS_ATTACK":"ATTACK",value:dmg,targetHp:target.hp,targetMaxHp:target.maxHp,critical:crit,defeated:target.hp<=0})}}const win=aliveUnits(A).length>0&&aliveUnits(D).length===0;turns.push({round:round+1,side:"SYSTEM",action:"RESULT",result:win?"WIN":"LOSE",attackerRemaining:aliveUnits(A).length,defenderRemaining:aliveUnits(D).length});return{win,turns,attackerPower:arenaPower(myState,myTeamIds),defenderPower:arenaPower(enemyState,enemyTeamIds)}}
function arenaSeasonKey(){const d=new Date(),y=d.getUTCFullYear(),m=String(d.getUTCMonth()+1).padStart(2,"0");return `${y}-${m}`}
function arenaWeekKey(){const d=new Date(),first=new Date(Date.UTC(d.getUTCFullYear(),0,1)),days=Math.floor((d-first)/86400000),week=Math.ceil((days+first.getUTCDay()+1)/7);return `${d.getUTCFullYear()}-W${String(week).padStart(2,"0")}`}
