function arenaRewardDefs(){return{daily:{target:3,reward:{arenaCoins:80,gems:30}},weekly:{target:10,reward:{arenaCoins:300,gems:120}},season:{target:1,reward:{arenaCoins:500,gems:200}}}}
async function arenaRewardState(env,a,p){const date=taipeiDate(),week=arenaWeekKey(),season=arenaSeasonKey(),dailyBattles=Number((await env.DB.prepare("SELECT COUNT(*) c FROM arena_battles WHERE player_id=? AND date(created_at)=?").bind(a.id,date).first())?.c||0),weeklyBattles=Number((await env.DB.prepare("SELECT COUNT(*) c FROM arena_battles WHERE player_id=? AND created_at>=datetime('now','-7 days')").bind(a.id).first())?.c||0),claims=(await env.DB.prepare("SELECT reward_type,period_key FROM arena_reward_claims WHERE player_id=?").bind(a.id).all()).results,claimed=(type,key)=>claims.some(x=>x.reward_type===type&&x.period_key===key),defs=arenaRewardDefs();return{daily:{progress:dailyBattles,target:defs.daily.target,claimed:claimed('daily',date),reward:defs.daily.reward},weekly:{progress:weeklyBattles,target:defs.weekly.target,claimed:claimed('weekly',week),reward:defs.weekly.reward},season:{progress:1,target:1,claimed:claimed('season',season),reward:{arenaCoins:defs.season.reward.arenaCoins+Math.max(0,Math.floor((Number(p.rating||1000)-1000)/100))*50,gems:defs.season.reward.gems}}}}
async function arenaPickOpponents(env,a,p,s){const myPower=arenaPower(s,(s.team||[]).slice(0,3)),candidates=(await env.DB.prepare(`SELECT p.id,p.display_name,ap.rating,ap.defense_team_json,ap.defense_strategy,gs.state_json FROM players p JOIN arena_profiles ap ON ap.player_id=p.id JOIN game_saves gs ON gs.player_id=p.id WHERE p.id<>? ORDER BY (ABS(ap.rating-?)*4 + ABS(p.stage_unlocked-?)*100) ASC,RANDOM() LIMIT 12`).bind(a.id,p.rating||1000,s.stageUnlocked||1).all()).results;return candidates.map(x=>{const os=parse(x.state_json,structuredClone(DEFAULT_STATE)),team=parse(x.defense_team_json,os.team||[]),power=arenaPower(os,team);return{id:x.id,displayName:x.display_name,rating:Number(x.rating||1000),tier:arenaTier(Number(x.rating||1000)),team,power,strategy:x.defense_strategy||"BALANCED",strategyLabel:arenaStrategyLabel(x.defense_strategy),matchScore:Math.abs(power-myPower)+Math.abs(Number(x.rating||1000)-Number(p.rating||1000))*3}}).sort((x,y)=>x.matchScore-y.matchScore).slice(0,3)}
