async function arenaFriendSearch(req,env,a){const q=String(new URL(req.url).searchParams.get("q")||"").trim();if(q.length<1)return J({rows:[]});const like=`%${q}%`,rows=(await env.DB.prepare(`SELECT p.id,p.display_name,p.picture_url,ap.friend_code,ap.rating,ap.wins,ap.losses FROM players p LEFT JOIN arena_profiles ap ON ap.player_id=p.id WHERE p.id<>? AND (UPPER(COALESCE(ap.friend_code,''))=UPPER(?) OR p.display_name LIKE ?) ORDER BY CASE WHEN UPPER(COALESCE(ap.friend_code,''))=UPPER(?) THEN 0 ELSE 1 END,p.display_name LIMIT 10`).bind(a.id,q,like,q).all()).results;return J({rows:rows.map(x=>({id:x.id,displayName:x.display_name,pictureUrl:x.picture_url||"",friendCode:x.friend_code||"",rating:Number(x.rating||1000),tier:arenaTier(Number(x.rating||1000)),wins:Number(x.wins||0),losses:Number(x.losses||0)}))})}
async function arenaAddFriend(req,env,a){const b=await req.json(),input=String(b.friendCode||b.friendPlayerId||"").trim();if(!input)return J({error:"INVALID_FRIEND"},400);let friend=await env.DB.prepare("SELECT p.id,p.display_name FROM players p LEFT JOIN arena_profiles ap ON ap.player_id=p.id WHERE UPPER(ap.friend_code)=UPPER(?) OR p.id=?").bind(input,input).first();if(!friend)return J({error:"PLAYER_NOT_FOUND"},404);if(friend.id===a.id)return J({error:"INVALID_FRIEND"},400);await env.DB.batch([env.DB.prepare("INSERT OR IGNORE INTO arena_friendships(player_id,friend_player_id)VALUES(?,?)").bind(a.id,friend.id),env.DB.prepare("INSERT OR IGNORE INTO arena_friendships(player_id,friend_player_id)VALUES(?,?)").bind(friend.id,a.id)]);return J({ok:true,friend})}
async function arenaLeaderboard(req,env,a){const scope=new URL(req.url).searchParams.get('scope')||'global';let sql=`SELECT p.id,p.display_name,ap.rating,ap.wins,ap.losses,ap.highest_rating FROM arena_profiles ap JOIN players p ON p.id=ap.player_id`,bind=[];if(scope==='friends'){sql+=` WHERE p.id IN (SELECT friend_player_id FROM arena_friendships WHERE player_id=?)`;bind=[a.id]}else if(scope==='guild'){const me=await env.DB.prepare("SELECT guild_id FROM arena_profiles WHERE player_id=?").bind(a.id).first();if(!me?.guild_id)return J({scope,rows:[],message:"尚未加入公會"});sql+=` WHERE ap.guild_id=?`;bind=[me.guild_id]}sql+=` ORDER BY ap.rating DESC,ap.wins DESC LIMIT 100`;const rows=(await env.DB.prepare(sql).bind(...bind).all()).results;return J({scope,rows:rows.map((x,i)=>({rank:i+1,id:x.id,displayName:x.display_name,rating:Number(x.rating||1000),tier:arenaTier(Number(x.rating||1000)),wins:Number(x.wins||0),losses:Number(x.losses||0),highestTier:arenaTier(Number(x.highest_rating||x.rating||1000)),isMe:x.id===a.id}))})}
async function arenaReplay(env,a,id){const b=await env.DB.prepare("SELECT * FROM arena_battles WHERE (battle_key=? OR CAST(id AS TEXT)=?) AND (player_id=? OR opponent_id=?)").bind(id,id,a.id,a.id).first();if(!b)return J({error:"NOT_FOUND"},404);return J({id:b.battle_key||String(b.id),result:b.result,battleType:b.battle_type||"RANKED",replay:parse(b.replay_json,[])})}
async function arenaLogs(req,env,a){const u=new URL(req.url),page=Math.max(1,Number(u.searchParams.get("page")||1)),pageSize=Math.min(50,Math.max(1,Number(u.searchParams.get("pageSize")||10))),q=String(u.searchParams.get("q")||"").trim(),range=String(u.searchParams.get("range")||"all");let where="(b.player_id=? OR b.opponent_id=?)",bind=[a.id,a.id];if(q){where+=` AND (CASE WHEN b.player_id=? THEN op.display_name ELSE atk.display_name END LIKE ? OR CASE WHEN b.player_id=? THEN opap.friend_code ELSE atkap.friend_code END LIKE ?)`;bind.push(a.id,`%${q}%`,a.id,`%${q}%`)}if(range==="today")where+=" AND date(b.created_at,'+8 hours')=date('now','+8 hours')";else if(range==="week")where+=" AND b.created_at>=datetime('now','-7 days')";else if(range==="month")where+=" AND b.created_at>=datetime('now','-30 days')";const total=Number((await env.DB.prepare(`SELECT COUNT(*) c FROM arena_battles b LEFT JOIN players op ON op.id=b.opponent_id LEFT JOIN players atk ON atk.id=b.player_id LEFT JOIN arena_profiles opap ON opap.player_id=op.id LEFT JOIN arena_profiles atkap ON atkap.player_id=atk.id WHERE ${where}`).bind(...bind).first())?.c||0),totalPages=Math.max(1,Math.ceil(total/pageSize)),safePage=Math.min(page,totalPages),offset=(safePage-1)*pageSize,rows=(await env.DB.prepare(`SELECT b.id,b.battle_key,b.result,b.rating_delta,b.created_at,b.player_id,b.opponent_id,b.battle_type,b.is_favorite,CASE WHEN b.player_id=? THEN op.display_name ELSE atk.display_name END opponent_name,CASE WHEN b.player_id=? THEN opap.friend_code ELSE atkap.friend_code END opponent_friend_code FROM arena_battles b LEFT JOIN players op ON op.id=b.opponent_id LEFT JOIN players atk ON atk.id=b.player_id LEFT JOIN arena_profiles opap ON opap.player_id=op.id LEFT JOIN arena_profiles atkap ON atkap.player_id=atk.id WHERE ${where} ORDER BY b.is_favorite DESC,b.id DESC LIMIT ? OFFSET ?`).bind(a.id,a.id,...bind,pageSize,offset).all()).results;return J({rows:rows.map(x=>({id:x.battle_key||String(x.id),result:x.opponent_id===a.id?(x.result==="WIN"?"LOSE":"WIN"):x.result,ratingDelta:x.opponent_id===a.id?-Number(x.rating_delta||0):Number(x.rating_delta||0),createdAt:x.created_at,opponentName:x.opponent_name||"未知玩家",opponentFriendCode:x.opponent_friend_code||"",battleType:x.battle_type||"RANKED",wasDefense:x.opponent_id===a.id,favorite:Number(x.is_favorite||0)===1})),total,page:safePage,pageSize,totalPages})}
async function arenaToggleFavorite(env,a,id){const b=await env.DB.prepare("SELECT id,is_favorite FROM arena_battles WHERE (battle_key=? OR CAST(id AS TEXT)=?) AND (player_id=? OR opponent_id=?)").bind(id,id,a.id,a.id).first();if(!b)return J({error:"NOT_FOUND"},404);const value=Number(b.is_favorite||0)?0:1;await env.DB.prepare("UPDATE arena_battles SET is_favorite=? WHERE id=?").bind(value,b.id).run();return J({ok:true,favorite:!!value})}
async function arenaDeleteReplay(env,a,id){const b=await env.DB.prepare("SELECT id FROM arena_battles WHERE (battle_key=? OR CAST(id AS TEXT)=?) AND (player_id=? OR opponent_id=?)").bind(id,id,a.id,a.id).first();if(!b)return J({error:"NOT_FOUND"},404);await env.DB.prepare("DELETE FROM arena_battles WHERE id=?").bind(b.id).run();return J({ok:true})}
async function arenaClaimReward(req,env,a){const {type}=await req.json(),s=await stateOf(env,a.id),p=await ensureArenaProfile(env,a,s),states=await arenaRewardState(env,a,p),r=states[type];if(!r)return J({error:"INVALID_REWARD"},400);if(r.claimed||r.progress<r.target)return J({error:"NOT_CLAIMABLE"},409);const key=type==='daily'?taipeiDate():type==='weekly'?arenaWeekKey():arenaSeasonKey();await env.DB.prepare("INSERT INTO arena_reward_claims(player_id,reward_type,period_key,reward_json)VALUES(?,?,?,?)").bind(a.id,type,key,JSON.stringify(r.reward)).run();if(r.reward.gems)s.gems+=r.reward.gems;await save(env,a.id,s);await env.DB.prepare("UPDATE arena_profiles SET arena_coins=arena_coins+? WHERE player_id=?").bind(Number(r.reward.arenaCoins||0),a.id).run();return J({ok:true,reward:r.reward,state:s})}

async function leaderboard(req,env){const me=await auth(req,env),rows=(await env.DB.prepare("SELECT p.id,p.display_name,p.stage_unlocked,COALESCE(SUM(CASE WHEN b.result='WIN' THEN 1 ELSE 0 END),0) wins FROM players p LEFT JOIN battle_records b ON b.player_id=p.id GROUP BY p.id ORDER BY p.stage_unlocked DESC,wins DESC,p.created_at ASC LIMIT 100").all()).results;return J({rows:rows.map(x=>({displayName:x.display_name,stageUnlocked:x.stage_unlocked,wins:x.wins,power:x.stage_unlocked*1000+x.wins*100,isMe:me?.id===x.id}))})}

async function adminRoutes(req,env,u){const ad=await adminAuth(req,env);if(!ad)return J({error:"ADMIN_UNAUTHORIZED"},401);if(u.pathname==="/api/admin/me")return J({ok:true});if(u.pathname==="/api/admin/logout"&&req.method==="POST"){const t=getCookie(req,ADMIN_COOKIE);if(t)await env.DB.prepare("DELETE FROM admin_sessions WHERE token_hash=?").bind(await sha(t)).run();return J({ok:true},200,{"Set-Cookie":cookie(ADMIN_COOKIE,"",0)})}if(u.pathname==="/api/admin/players"){const players=(await env.DB.prepare(`SELECT p.id,p.display_name,p.gold,p.gems,p.energy,p.max_energy,p.stage_unlocked,p.last_login_at,r.status AS restriction_status,r.reason AS restriction_reason,r.suspended_until FROM players p LEFT JOIN player_restrictions r ON r.player_id=p.id ORDER BY p.last_login_at DESC LIMIT 200`).all()).results.map(x=>({...x,suspended:x.restriction_status==="SUSPENDED"&&(!x.suspended_until||new Date(x.suspended_until)>new Date())}));return J({players})}if(u.pathname==="/api/admin/resources"&&req.method==="POST"){const b=await req.json();if(!b.playerId)return J({error:"PLAYER_REQUIRED"},400);const s=await stateOf(env,b.playerId),d={gold:limit(b.gold,-1e7,1e7),gems:limit(b.gems,-1e7,1e7),energy:limit(b.energy,-1e5,1e5)};s.gold=Math.max(0,s.gold+d.gold);s.gems=Math.max(0,s.gems+d.gems);s.energy=Math.max(0,Math.min(100000,s.energy+d.energy));await save(env,b.playerId,s);await log(env,"RESOURCE_ADJUST",b.playerId,d,b.reason);return J({ok:true,state:s})}if(u.pathname==="/api/admin/mail"&&req.method==="POST"){const b=await req.json(),reward={gold:Math.max(0,limit(b.reward?.gold,0,1e7)),gems:Math.max(0,limit(b.reward?.gems,0,1e7)),energy:Math.max(0,limit(b.reward?.energy,0,1e5))};let ids=b.playerId?[b.playerId]:(await env.DB.prepare("SELECT id FROM players").all()).results.map(x=>x.id);const q=ids.map(id=>env.DB.prepare("INSERT INTO player_mail(id,player_id,title,body,reward_json)VALUES(?,?,?,?,?)").bind(crypto.randomUUID(),id,String(b.title||"營運補償").slice(0,80),String(b.body||"請領取附件獎勵。").slice(0,500),JSON.stringify(reward)));for(let i=0;i<q.length;i+=50)await env.DB.batch(q.slice(i,i+50));await log(env,"SEND_MAIL",b.playerId||"ALL",{count:ids.length,reward},b.title);return J({ok:true,count:ids.length})}if(u.pathname==="/api/admin/suspend"&&req.method==="POST"){const b=await req.json();if(!b.playerId||!String(b.reason||"").trim())return J({error:"PLAYER_AND_REASON_REQUIRED"},400);await env.DB.prepare(`INSERT INTO player_restrictions(player_id,status,reason,suspended_until,updated_at) VALUES(?,'SUSPENDED',?,?,CURRENT_TIMESTAMP) ON CONFLICT(player_id) DO UPDATE SET status='SUSPENDED',reason=excluded.reason,suspended_until=excluded.suspended_until,updated_at=CURRENT_TIMESTAMP`).bind(b.playerId,String(b.reason).slice(0,300),b.until||null).run();await env.DB.prepare("DELETE FROM sessions WHERE player_id=?").bind(b.playerId).run();await log(env,"SUSPEND_PLAYER",b.playerId,{until:b.until||null},b.reason);return J({ok:true})}if(u.pathname==="/api/admin/unsuspend"&&req.method==="POST"){const b=await req.json();if(!b.playerId)return J({error:"PLAYER_REQUIRED"},400);await env.DB.prepare("DELETE FROM player_restrictions WHERE player_id=?").bind(b.playerId).run();await log(env,"UNSUSPEND_PLAYER",b.playerId,{},"");return J({ok:true})}if(u.pathname==="/api/admin/player/delete"&&req.method==="POST"){const b=await req.json();if(b.confirmation!=="DELETE"||!b.playerId)return J({error:"DELETE_CONFIRMATION_REQUIRED"},400);const player=await env.DB.prepare("SELECT id,line_user_id,display_name FROM players WHERE id=?").bind(b.playerId).first();if(!player)return J({error:"PLAYER_NOT_FOUND"},404);await env.DB.batch([env.DB.prepare("INSERT INTO deleted_player_audit(player_id,line_user_id,display_name,reason)VALUES(?,?,?,?)").bind(player.id,player.line_user_id||"",player.display_name||"",String(b.reason||"").slice(0,300)),env.DB.prepare("DELETE FROM players WHERE id=?").bind(player.id)]);await log(env,"DELETE_PLAYER",player.id,{lineUserId:player.line_user_id||""},b.reason);return J({ok:true})}if(u.pathname==="/api/admin/arena/search"&&req.method==="GET")return await adminArenaSearch(req,env);if(u.pathname==="/api/admin/arena/player"&&req.method==="GET")return await adminArenaPlayer(req,env);if(u.pathname==="/api/admin/arena/update"&&req.method==="POST")return await adminArenaUpdate(req,env);if(u.pathname==="/api/admin/arena/attempts"&&req.method==="POST")return await adminArenaAttempts(req,env);if(u.pathname==="/api/admin/arena/clear-battles"&&req.method==="POST")return await adminArenaClearBattles(req,env);if(u.pathname==="/api/admin/arena/reset-player-season"&&req.method==="POST")return await adminArenaResetPlayerSeason(req,env);if(u.pathname==="/api/admin/arena/reset-season"&&req.method==="POST")return await adminArenaResetSeason(req,env);if(u.pathname==="/api/admin/arena/reset-leaderboard"&&req.method==="POST")return await adminArenaResetLeaderboard(req,env);if(u.pathname==="/api/admin/catalog/sync-defaults"&&req.method==="POST")return await catalogSyncStatus(env);if(u.pathname==="/api/admin/media/upload"&&req.method==="POST")return await mediaUpload(req,env);if(u.pathname.startsWith("/api/admin/catalog/")){const p=u.pathname.split("/").filter(Boolean),entity=p[3],id=p[4]||"";if(req.method==="GET")return await catalogList(env,entity);if(req.method==="POST")return await catalogSave(req,env,entity);if(req.method==="DELETE")return await catalogDelete(env,entity,id)}if(u.pathname==="/api/admin/logs"){const logs=(await env.DB.prepare("SELECT * FROM admin_logs ORDER BY id DESC LIMIT 100").all()).results;return J({logs})}return J({error:"NOT_FOUND"},404)}
async function adminArenaSearch(req,env){const q=String(new URL(req.url).searchParams.get("q")||"").trim();if(!q)return J({rows:[]});const like=`%${q}%`,rows=(await env.DB.prepare(`SELECT p.id,p.display_name,p.line_user_id,ap.rating,ap.arena_coins,ap.wins,ap.losses,ap.highest_rating,ap.friend_code FROM players p LEFT JOIN arena_profiles ap ON ap.player_id=p.id WHERE p.id LIKE ? OR p.display_name LIKE ? OR p.line_user_id LIKE ? OR ap.friend_code LIKE ? ORDER BY p.display_name LIMIT 30`).bind(like,like,like,like).all()).results;return J({rows:rows.map(x=>({id:x.id,displayName:x.display_name,lineUserId:x.line_user_id||"",rating:Number(x.rating||1000),arenaCoins:Number(x.arena_coins||0),tier:arenaTier(Number(x.rating||1000)),wins:Number(x.wins||0),losses:Number(x.losses||0),highestRating:Number(x.highest_rating||x.rating||1000),friendCode:x.friend_code||""}))})}
async function adminArenaPlayer(req,env){const id=String(new URL(req.url).searchParams.get("playerId")||"").trim();if(!id)return J({error:"PLAYER_REQUIRED"},400);const p=await env.DB.prepare(`SELECT p.id,p.display_name,p.line_user_id,p.picture_url,ap.* FROM players p LEFT JOIN arena_profiles ap ON ap.player_id=p.id WHERE p.id=?`).bind(id).first();if(!p)return J({error:"PLAYER_NOT_FOUND"},404);if(!p.season_key){const s=await stateOf(env,id);await ensureArenaProfile(env,{id},s)}const row=await env.DB.prepare(`SELECT p.id,p.display_name,p.line_user_id,p.picture_url,ap.* FROM players p JOIN arena_profiles ap ON ap.player_id=p.id WHERE p.id=?`).bind(id).first(),date=taipeiDate(),used=Number((await env.DB.prepare("SELECT used_count FROM arena_daily_attempts WHERE player_id=? AND attempt_date=?").bind(id,date).first())?.used_count||0),battleCount=Number((await env.DB.prepare("SELECT COUNT(*) c FROM arena_battles WHERE player_id=? OR opponent_id=?").bind(id,id).first())?.c||0),friendCount=Number((await env.DB.prepare("SELECT COUNT(*) c FROM arena_friendships WHERE player_id=?").bind(id).first())?.c||0),total=Number(row.wins||0)+Number(row.losses||0);return J({player:{id:row.id,displayName:row.display_name,lineUserId:row.line_user_id||"",pictureUrl:row.picture_url||"",rating:Number(row.rating||1000),arenaCoins:Number(row.arena_coins||0),tier:arenaTier(Number(row.rating||1000)),wins:Number(row.wins||0),losses:Number(row.losses||0),winRate:total?Math.round(Number(row.wins||0)*1000/total)/10:0,highestRating:Number(row.highest_rating||row.rating||1000),highestTier:arenaTier(Number(row.highest_rating||row.rating||1000)),currentStreak:Number(row.current_streak||0),bestStreak:Number(row.best_streak||0),seasonKey:row.season_key||arenaSeasonKey(),friendCode:row.friend_code||"",usedToday:used,remainingToday:Math.max(0,5-used),battleCount,friendCount}})}
async function adminArenaUpdate(req,env){const b=await req.json(),id=String(b.playerId||"").trim();if(!id)return J({error:"PLAYER_REQUIRED"},400);const old=await env.DB.prepare("SELECT * FROM arena_profiles WHERE player_id=?").bind(id).first();if(!old)return J({error:"ARENA_PROFILE_NOT_FOUND"},404);let rating=limit(b.rating,0,999999),coins=limit(b.arenaCoins,0,999999999),wins=limit(b.wins,0,999999999),losses=limit(b.losses,0,999999999),bestStreak=limit(b.bestStreak,0,999999999),currentStreak=limit(b.currentStreak,0,999999999),highest=limit(b.highestRating,0,999999);if(highest<rating)highest=rating;await env.DB.prepare(`UPDATE arena_profiles SET rating=?,arena_coins=?,wins=?,losses=?,current_streak=?,best_streak=?,highest_rating=?,season_high_rating=MAX(season_high_rating,?),updated_at=CURRENT_TIMESTAMP WHERE player_id=?`).bind(rating,coins,wins,losses,currentStreak,bestStreak,highest,rating,id).run();await log(env,"ARENA_UPDATE",id,{before:{rating:old.rating,arenaCoins:old.arena_coins,wins:old.wins,losses:old.losses},after:{rating,arenaCoins:coins,wins,losses,currentStreak,bestStreak,highestRating:highest}},b.reason||"");return adminArenaPlayer(new Request(new URL(`/api/admin/arena/player?playerId=${encodeURIComponent(id)}`,req.url)),env)}
async function adminArenaAttempts(req,env){const b=await req.json(),id=String(b.playerId||"").trim();if(!id)return J({error:"PLAYER_REQUIRED"},400);const date=taipeiDate(),mode=String(b.mode||"add"),amount=limit(b.amount,0,999999),row=await env.DB.prepare("SELECT used_count FROM arena_daily_attempts WHERE player_id=? AND attempt_date=?").bind(id,date).first();let used=Number(row?.used_count||0),before=used;if(mode==="reset")used=0;else if(mode==="setRemaining")used=Math.max(0,5-limit(b.remaining,0,999999));else if(mode==="add")used=Math.max(0,used-amount);else return J({error:"INVALID_MODE"},400);await env.DB.prepare(`INSERT INTO arena_daily_attempts(player_id,attempt_date,used_count)VALUES(?,?,?) ON CONFLICT(player_id,attempt_date) DO UPDATE SET used_count=excluded.used_count`).bind(id,date,used).run();await log(env,"ARENA_ATTEMPTS",id,{beforeUsed:before,afterUsed:used,mode,amount},b.reason||"");return adminArenaPlayer(new Request(new URL(`/api/admin/arena/player?playerId=${encodeURIComponent(id)}`,req.url)),env)}
async function adminArenaClearBattles(req,env){const b=await req.json(),id=String(b.playerId||"").trim();if(!id)return J({error:"PLAYER_REQUIRED"},400);const c=Number((await env.DB.prepare("SELECT COUNT(*) c FROM arena_battles WHERE player_id=? OR opponent_id=?").bind(id,id).first())?.c||0);await env.DB.prepare("DELETE FROM arena_battles WHERE player_id=? OR opponent_id=?").bind(id,id).run();await log(env,"ARENA_CLEAR_BATTLES",id,{deleted:c},b.reason||"");return J({ok:true,deleted:c})}
async function adminArenaResetPlayerSeason(req,env){const b=await req.json(),id=String(b.playerId||"").trim();if(!id)return J({error:"PLAYER_REQUIRED"},400);await env.DB.prepare("UPDATE arena_profiles SET rating=1000,wins=0,losses=0,current_streak=0,season_high_rating=1000,season_key=?,updated_at=CURRENT_TIMESTAMP WHERE player_id=?").bind(arenaSeasonKey(),id).run();await log(env,"ARENA_RESET_PLAYER_SEASON",id,{season:arenaSeasonKey()},b.reason||"");return adminArenaPlayer(new Request(new URL(`/api/admin/arena/player?playerId=${encodeURIComponent(id)}`,req.url)),env)}
async function adminArenaResetSeason(req,env){const b=await req.json(),count=Number((await env.DB.prepare("SELECT COUNT(*) c FROM arena_profiles").first())?.c||0);await env.DB.batch([env.DB.prepare("UPDATE arena_profiles SET rating=1000,wins=0,losses=0,current_streak=0,season_high_rating=1000,season_key=?,opponent_ids_json='[]',next_free_refresh_at=NULL,updated_at=CURRENT_TIMESTAMP").bind(arenaSeasonKey()),env.DB.prepare("DELETE FROM arena_daily_attempts"),env.DB.prepare("DELETE FROM arena_reward_claims")]);await log(env,"ARENA_RESET_SEASON","ALL",{players:count,season:arenaSeasonKey()},b.reason||"");return J({ok:true,players:count,seasonKey:arenaSeasonKey()})}
async function adminArenaResetLeaderboard(req,env){const b=await req.json(),count=Number((await env.DB.prepare("SELECT COUNT(*) c FROM arena_profiles").first())?.c||0);await env.DB.prepare("UPDATE arena_profiles SET rating=1000,wins=0,losses=0,current_streak=0,season_high_rating=1000,updated_at=CURRENT_TIMESTAMP").run();await log(env,"ARENA_RESET_LEADERBOARD","ALL",{players:count},b.reason||"");return J({ok:true,players:count})}

async function adminLogin(req,env){if(!env.ADMIN_PASSWORD)throw Error("ADMIN_PASSWORD_NOT_CONFIGURED");const b=await req.json();if(!await eq(String(b.password||""),String(env.ADMIN_PASSWORD)))return J({error:"INVALID_PASSWORD"},401);const token=rand(),hash=await sha(token);await env.DB.prepare("INSERT INTO admin_sessions(token_hash,expires_at)VALUES(?,datetime('now','+12 hours'))").bind(hash).run();return J({ok:true},200,{"Set-Cookie":cookie(ADMIN_COOKIE,token,.5)})}
async function adminAuth(req,env){const t=getCookie(req,ADMIN_COOKIE);if(!t)return null;return await env.DB.prepare("SELECT * FROM admin_sessions WHERE token_hash=? AND expires_at>CURRENT_TIMESTAMP").bind(await sha(t)).first()}
async function auth(req,env){const t=getCookie(req,COOKIE_NAME);if(!t)return null;const s=await env.DB.prepare("SELECT player_id FROM sessions WHERE token_hash=? AND expires_at>CURRENT_TIMESTAMP").bind(await sha(t)).first();if(!s)return null;const p=await env.DB.prepare("SELECT * FROM players WHERE id=?").bind(s.player_id).first();if(!p)return null;const r=await env.DB.prepare("SELECT * FROM player_restrictions WHERE player_id=?").bind(p.id).first();if(r?.status==="SUSPENDED"&&(!r.suspended_until||new Date(r.suspended_until)>new Date()))return null;return p}
async function startLine(req,env){if(!env.LINE_CHANNEL_ID||!env.LINE_CALLBACK_URL)return new Response("LINE login not configured",{status:500});const state=rand();await env.DB.prepare("INSERT INTO oauth_states(state_hash,expires_at)VALUES(?,datetime('now','+10 minutes'))").bind(await sha(state)).run();const u=new URL("https://access.line.me/oauth2/v2.1/authorize");u.searchParams.set("response_type","code");u.searchParams.set("client_id",env.LINE_CHANNEL_ID);u.searchParams.set("redirect_uri",env.LINE_CALLBACK_URL);u.searchParams.set("state",state);u.searchParams.set("scope","profile openid");return Response.redirect(u.toString(),302)}
async function callback(req,env){const u=new URL(req.url),code=u.searchParams.get("code"),state=u.searchParams.get("state");if(!code||!state)throw Error("LINE_CALLBACK_INVALID");const row=await env.DB.prepare("SELECT * FROM oauth_states WHERE state_hash=? AND expires_at>CURRENT_TIMESTAMP").bind(await sha(state)).first();if(!row)throw Error("LINE_STATE_INVALID");await env.DB.prepare("DELETE FROM oauth_states WHERE state_hash=?").bind(await sha(state)).run();const tokenRes=await fetch("https://api.line.me/oauth2/v2.1/token",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:new URLSearchParams({grant_type:"authorization_code",code,redirect_uri:env.LINE_CALLBACK_URL,client_id:env.LINE_CHANNEL_ID,client_secret:env.LINE_CHANNEL_SECRET})}),token=await tokenRes.json();if(!token.access_token)throw Error("LINE_TOKEN_FAILED");const profile=await fetch("https://api.line.me/v2/profile",{headers:{Authorization:`Bearer ${token.access_token}`}}).then(r=>r.json());let p=await env.DB.prepare("SELECT * FROM players WHERE line_user_id=?").bind(profile.userId).first();if(!p){const id=crypto.randomUUID();await env.DB.prepare("INSERT INTO players(id,line_user_id,display_name,picture_url)VALUES(?,?,?,?)").bind(id,profile.userId,profile.displayName||"玩家",profile.pictureUrl||"").run();p=await env.DB.prepare("SELECT * FROM players WHERE id=?").bind(id).first()}else await env.DB.prepare("UPDATE players SET display_name=?,picture_url=?,last_login_at=CURRENT_TIMESTAMP WHERE id=?").bind(profile.displayName||p.display_name,profile.pictureUrl||p.picture_url,p.id).run();const t=rand();await env.DB.prepare("INSERT INTO sessions(token_hash,player_id,expires_at)VALUES(?,?,datetime('now',?))").bind(await sha(t),p.id,`+${SESSION_DAYS} days`).run();return Response.redirect(new URL("/?login=success",req.url).toString(),302,{headers:{"Set-Cookie":cookie(COOKIE_NAME,t,SESSION_DAYS)}})}
async function logout(req,env){const t=getCookie(req,COOKIE_NAME);if(t)await env.DB.prepare("DELETE FROM sessions WHERE token_hash=?").bind(await sha(t)).run();return J({ok:true},200,{"Set-Cookie":cookie(COOKIE_NAME,"",0)})}
async function lineDiagnostics(env){return J({ok:!!(env.LINE_CHANNEL_ID&&env.LINE_CHANNEL_SECRET&&env.LINE_CALLBACK_URL),callback:env.LINE_CALLBACK_URL||""})}
function loginErrorPage(e,req){return Response.redirect(new URL(`/?login=error&reason=${encodeURIComponent(safeError(e))}`,req.url).toString(),302)}
async function stateOf(env,id){const p=await env.DB.prepare("SELECT * FROM players WHERE id=?").bind(id).first(),g=await env.DB.prepare("SELECT state_json FROM game_saves WHERE player_id=?").bind(id).first();let s=g?parse(g.state_json,structuredClone(DEFAULT_STATE)):structuredClone(DEFAULT_STATE);s={...structuredClone(DEFAULT_STATE),...s};s.gold=Number(p?.gold??s.gold);s.gems=Number(p?.gems??s.gems);s.energy=Number(p?.energy??s.energy);s.maxEnergy=Number(p?.max_energy??s.maxEnergy);s.stageUnlocked=Number(p?.stage_unlocked??s.stageUnlocked);s.inventory={...structuredClone(DEFAULT_STATE.inventory),...(s.inventory||{}),equipment:{...structuredClone(DEFAULT_STATE.inventory.equipment),...(s.inventory?.equipment||{})}};s.equipmentMeta=s.equipmentMeta||{};return s}
async function save(env,id,s){await env.DB.batch([env.DB.prepare("UPDATE players SET gold=?,gems=?,energy=?,max_energy=?,stage_unlocked=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(s.gold,s.gems,s.energy,s.maxEnergy,s.stageUnlocked,id),env.DB.prepare(`INSERT INTO game_saves(player_id,state_json)VALUES(?,?) ON CONFLICT(player_id) DO UPDATE SET state_json=excluded.state_json,updated_at=CURRENT_TIMESTAMP`).bind(id,JSON.stringify(s))])}
async function log(env,action,target,data,reason){await env.DB.prepare("INSERT INTO admin_logs(action,target_player_id,data_json,reason)VALUES(?,?,?,?)").bind(action,target,JSON.stringify(data||{}),String(reason||"").slice(0,300)).run()}
async function publicCatalog(env){return J({heroes:(await env.DB.prepare("SELECT * FROM catalog_heroes WHERE active=1 ORDER BY sort_order,id").all()).results,equipment:(await env.DB.prepare("SELECT * FROM catalog_equipment WHERE active=1 ORDER BY sort_order,id").all()).results,shopProducts:(await env.DB.prepare("SELECT * FROM catalog_shop_products WHERE active=1 ORDER BY sort_order,id").all()).results,announcements:(await env.DB.prepare("SELECT * FROM announcements WHERE active=1 ORDER BY pinned DESC,priority DESC,created_at DESC").all()).results,banners:(await env.DB.prepare("SELECT * FROM banners WHERE active=1 ORDER BY sort_order,id").all()).results})}
async function catalogSyncStatus(){return J({ok:true,inserted:0})}
async function catalogList(env,entity){const map={heroes:"catalog_heroes",skills:"catalog_skills",equipment:"catalog_equipment",items:"catalog_items","shop-products":"catalog_shop_products",dungeons:"catalog_dungeons",events:"catalog_events","login-rewards":"catalog_login_rewards",announcements:"announcements",banners:"banners"},table=map[entity];if(!table)return J({error:"NOT_FOUND"},404);return J({rows:(await env.DB.prepare(`SELECT * FROM ${table} ORDER BY id`).all()).results})}
async function catalogSave(req,env,entity){return J({ok:true})}
async function catalogDelete(env,entity,id){return J({ok:true})}
async function mediaUpload(){return J({error:"NOT_IMPLEMENTED"},501)}
function applyReward(s,r){s.gold+=Number(r.gold||0);s.gems+=Number(r.gems||0);s.energy=Math.min(s.maxEnergy,s.energy+Number(r.energy||0));for(const k of ["wood","ore","herb","core","potion","energyPotion"])if(r[k])s.inventory[k]=(s.inventory[k]||0)+Number(r[k])}
function rewardLabel(r){return Object.entries(r||{}).map(([k,v])=>`${k}:${v}`).join("、")}
function arenaTier(r){return r>=2500?"王者":r>=2200?"大師":r>=1900?"鑽石":r>=1600?"白金":r>=1300?"黃金":r>=1100?"白銀":"青銅"}
function limit(v,min,max){v=Number(v||0);return Math.max(min,Math.min(max,Math.trunc(v)))}
function parse(s,f){try{return JSON.parse(s)}catch{return f}}
function safeError(e){return String(e?.message||e||"UNKNOWN_ERROR").slice(0,300)}
function taipeiDate(){return new Intl.DateTimeFormat("en-CA",{timeZone:"Asia/Taipei",year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date())}
function rand(){return crypto.randomUUID()+crypto.randomUUID()}
async function sha(s){const b=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(s));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,"0")).join("")}
async function eq(a,b){if(a.length!==b.length)return false;let x=0;for(let i=0;i<a.length;i++)x|=a.charCodeAt(i)^b.charCodeAt(i);return x===0}
function getCookie(req,n){return (req.headers.get("Cookie")||"").split(/;\s*/).map(x=>x.split("=")).find(x=>x[0]===n)?.[1]||""}
function cookie(n,v,days){return `${n}=${v}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${Math.max(0,Math.round(days*86400))}`}
function J(x,s=200,h={}){return new Response(JSON.stringify(x),{status:s,headers:{"Content-Type":"application/json;charset=utf-8","Cache-Control":"no-store",...h}})}
